CREATE TABLE accounts (id TEXT PRIMARY KEY, tesla_sub_hash TEXT UNIQUE, label TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL, disabled INTEGER NOT NULL DEFAULT 0);
INSERT INTO accounts(id, label, created) VALUES ('', 'owner', CAST(strftime('%s','now') AS INTEGER) * 1000);
CREATE TABLE invites (hash TEXT PRIMARY KEY, label TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL, expires INTEGER NOT NULL, used_at INTEGER, account TEXT);
CREATE TABLE mcp_tokens (hash TEXT PRIMARY KEY, account TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL);
CREATE INDEX mcp_tokens_account ON mcp_tokens(account);
CREATE TABLE telemetry_vehicles (vin_hash TEXT PRIMARY KEY, account TEXT NOT NULL, vehicle_id TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX telemetry_vehicles_account ON telemetry_vehicles(account);
ALTER TABLE sessions ADD COLUMN account TEXT NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN role TEXT NOT NULL DEFAULT 'operator';
CREATE TABLE oauth_states_v3 (hash TEXT PRIMARY KEY, browser_hash TEXT NOT NULL, expires INTEGER NOT NULL, purpose TEXT NOT NULL DEFAULT 'connect' CHECK(purpose IN ('connect', 'reconnect', 'signup', 'signin')), account TEXT DEFAULT '', role TEXT DEFAULT 'operator', invite_hash TEXT);
INSERT INTO oauth_states_v3(hash, browser_hash, expires, purpose, account, role) SELECT hash, browser_hash, expires, purpose, '', 'operator' FROM oauth_states;
DROP TABLE oauth_states;
ALTER TABLE oauth_states_v3 RENAME TO oauth_states;
CREATE TABLE usage_v3 (account TEXT NOT NULL DEFAULT '', month TEXT NOT NULL, day TEXT NOT NULL, category TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, estimated_usd REAL NOT NULL DEFAULT 0, PRIMARY KEY(account, day, category));
INSERT INTO usage_v3(account, month, day, category, count, estimated_usd) SELECT '', month, day, category, count, estimated_usd FROM usage;
DROP TABLE usage;
ALTER TABLE usage_v3 RENAME TO usage;
CREATE INDEX usage_month ON usage(month);
ALTER TABLE audit ADD COLUMN account TEXT NOT NULL DEFAULT '';
